content='''def transform(grid):
    # Identify 5-cell diamond motifs (center plus four orthogonal arms).
    h, w = len(grid), len(grid[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and grid[r-1][c]==2 and grid[r+1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2:
                centers.append((r,c))
    out=[row[:] for row in grid]
    # Join collinear motif centers with color 1; extend from any center to
    # the next existing 2 marker in that same row or column.
    for r,c in centers:
        for rr,cc in centers:
            if rr==r and cc!=c:
                for x in range(min(c,cc)+1,max(c,cc)):
                    if grid[r][x]==0: out[r][x]=1
            if cc==c and rr!=r:
                for y in range(min(r,rr)+1,max(r,rr)):
                    if grid[y][c]==0: out[y][c]=1
    for r,c in centers:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=r+dr,c+dc
            while 0<=y<h and 0<=x<w and grid[y][x]==0:
                # extend only if eventually reaching a 2 marker in this direction
                y+=dr; x+=dc
            if 0<=y<h and 0<=x<w and grid[y][x]==2:
